        <Card className="bg-cosmic-800/50 border-cosmic-600">
          <CardHeader>
            <CardTitle className="flex items-center justify-between">
              <span>Visualization Controls</span>
              <div className="flex items-center space-x-2">
                <Button
                  size="sm"
