          <CardContent>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
              {/* Visualization Type */}
              <div>
                <label className="text-sm font-medium text-cosmic-200 mb-2 block">
                  Visualization Type
