              {/* Frequency */}
              <div>
                <label className="text-sm font-medium text-cosmic-200 mb-2 block">
                  Frequency: {frequency[0]}Hz
                </label>
                <Slider
                  value={frequency}
                  onValueChange={setFrequency}
                  min={100}
                  max={1000}
                  step={10}
