                />
              </div>

              {/* Options */}
              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <label className="text-sm text-cosmic-200">Audio Guidance</label>
                  <Switch 
                    checked={audioEnabled} 
                    onCheckedChange={setAudioEnabled}
                  />
                </div>
                <div className="flex items-center justify-between">
                  <label className="text-sm text-cosmic-200">Auto Rotate</label>
                  <Switch 
                    checked={autoRotate} 
                    onCheckedChange={setAutoRotate}
                  />
                </div>
              </div>
            </div>

            {/* Action Buttons */}
            <div className="flex items-center justify-center space-x-4 mt-6">
              <Button
                onClick={isPlaying ? stopVisualization : startVisualization}
                className="bg-sacred-gold hover:bg-sacred-gold/80 text-cosmic-900 font-semibold px-6"
              >
                {isPlaying ? (
                  <>
                    <Pause className="w-4 h-4 mr-2" />
                    Stop
                  </>
                ) : (
                  <>
                    <Play className="w-4 h-4 mr-2" />
                    Start
                  </>
                )}
              </Button>

              <Button
                onClick={resetVisualization}
                variant="outline"
                className="border-cosmic-600 text-cosmic-200"
              >
                <RotateCcw className="w-4 h-4 mr-2" />
                Reset
              </Button>

              <Button
                onClick={() => setAudioEnabled(!audioEnabled)}
                variant="outline"
                className="border-cosmic-600 text-cosmic-200"
              >
                {audioEnabled ? (
                  <Volume2 className="w-4 h-4" />
                ) : (
                  <VolumeX className="w-4 h-4" />
                )}
              </Button>
            </div>
          </CardContent>
        </Card>
      </motion.div>

      {/* Visualization Area */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-8">
        {/* Particle System Canvas */}
        <motion.div
          initial={{ opacity: 0, x: -20 }}
          animate={{ opacity: 1, x: 0 }}
        >
          <Card className="bg-cosmic-800/50 border-cosmic-600 h-[500px]">
            <CardHeader>
              <CardTitle className="flex items-center space-x-2">
                <Zap className="w-5 h-5 text-sacred-gold" />
                <span>Interactive Particle System</span>
                {isPlaying && (
                  <Badge variant="outline" className="border-green-400 text-green-400">
                    Active
                  </Badge>
                )}
              </CardTitle>
            </CardHeader>
            <CardContent className="h-[400px] relative">
              <canvas
                ref={canvasRef}
                className="w-full h-full rounded-lg border border-cosmic-600 bg-cosmic-900"
                style={{ 
                  background: 'radial-gradient(circle at center, rgba(15, 10, 40, 0.9) 0%, rgba(5, 2, 15, 1) 100%)'
                }}
              />

              {/* Current Visualization Info */}
              <div className="absolute top-4 left-4 bg-cosmic-800/80 rounded-lg p-3 border border-cosmic-600">
                <div className="text-sm font-medium text-sacred-gold">
                  {visualizations.find(v => v.id === currentVisualization)?.name}
                </div>
                <div className="text-xs text-cosmic-300 mt-1">
                  {visualizations.find(v => v.id === currentVisualization)?.description}
                </div>
              </div>
            </CardContent>
          </Card>
        </motion.div>

        {/* Sacred Geometry Canvas */}
        <motion.div
          initial={{ opacity: 0, x: 20 }}
          animate={{ opacity: 1, x: 0 }}
        >
          <Card className="bg-cosmic-800/50 border-cosmic-600 h-[500px]">
            <CardHeader>
              <CardTitle className="flex items-center space-x-2">
                <Eye className="w-5 h-5 text-sacred-gold" />
                <span>Sacred Geometry Patterns</span>
              </CardTitle>
            </CardHeader>
            <CardContent className="h-[400px]">
              <canvas
                ref={geometryCanvasRef}
                className="w-full h-full rounded-lg border border-cosmic-600"
              />
            </CardContent>
          </Card>
        </motion.div>
      </div>

      {/* Performance Metrics */}
      {showMetrics && (
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
        >
          <Card className="bg-cosmic-800/50 border-cosmic-600">
            <CardHeader>
              <CardTitle>Real-time Performance Metrics</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <div className="text-center p-4 bg-cosmic-700/50 rounded-lg">
                  <div className="text-2xl font-bold text-green-400">{metrics.fps}</div>
                  <div className="text-sm text-cosmic-300">FPS</div>
                </div>

                <div className="text-center p-4 bg-cosmic-700/50 rounded-lg">
                  <div className="text-2xl font-bold text-blue-400">{metrics.particles}</div>
                  <div className="text-sm text-cosmic-300">Particles</div>
                </div>

                <div className="text-center p-4 bg-cosmic-700/50 rounded-lg">
                  <div className="text-2xl font-bold text-purple-400">{metrics.renderTime.toFixed(1)}ms</div>
                  <div className="text-sm text-cosmic-300">Render Time</div>
                </div>

                <div className="text-center p-4 bg-cosmic-700/50 rounded-lg">
                  <div className="text-2xl font-bold text-yellow-400">{metrics.memoryUsage.toFixed(1)}MB</div>
                  <div className="text-sm text-cosmic-300">Memory</div>
                </div>
              </div>
            </CardContent>
          </Card>
        </motion.div>
      )}
    </div>
  );
}

client/src/components/ui/chart.tsx.content:
"use client"

import * as React from "react"
import * as RechartsPrimitive from "recharts"

import { cn } from "@/lib/utils"

// Format: { THEME_NAME: CSS_SELECTOR }
const THEMES = { light: "", dark: ".dark" } as const

export type ChartConfig = {
  [k in string]: {
    label?: React.ReactNode
    icon?: React.ComponentType
  } & (
    | { color?: string; theme?: never }
    | { color?: never; theme: Record<keyof typeof THEMES, string> }
  )
}

type ChartContextProps = {
  config: ChartConfig
}

const ChartContext = React.createContext<ChartContextProps | null>(null)

function useChart() {
  const context = React.useContext(ChartContext)

  if (!context) {
    throw new Error("useChart must be used within a <ChartContainer />")
  }

  return context
}

const ChartContainer = React.forwardRef<
  HTMLDivElement,
  React.ComponentProps<"div"> & {
    config: ChartConfig
    children: React.ComponentProps<
      typeof RechartsPrimitive.ResponsiveContainer
    >["children"]
  }
>(({ id, className, children, config, ...props }, ref) => {
  const uniqueId = React.useId()
  const chartId = `chart-${id || uniqueId.replace(/:/g, "")}`

  return (
    <ChartContext.Provider value={{ config }}>
      <div
        data-chart={chartId}
        ref={ref}
        className={cn(
          "flex aspect-video justify-center text-xs [&_.recharts-cartesian-axis-tick_text]:fill-muted-foreground [&_.recharts-cartesian-grid_line[stroke='#ccc']]:stroke-border/50 [&_.recharts-curve.recharts-tooltip-cursor]:stroke-border [&_.recharts-dot[stroke='#fff']]:stroke-transparent [&_.recharts-layer]:outline-none [&_.recharts-polar-grid_[stroke='#ccc']]:stroke-border [&_.recharts-radial-bar-background-sector]:fill-muted [&_.recharts-rectangle.recharts-tooltip-cursor]:fill-muted [&_.recharts-reference-line_[stroke='#ccc']]:stroke-border [&_.recharts-sector[stroke='#fff']]:stroke-transparent [&_.recharts-sector]:outline-none [&_.recharts-surface]:outline-none",
          className
        )}
        {...props}
      >
        <ChartStyle id={chartId} config={config} />
        <RechartsPrimitive.ResponsiveContainer>
          {children}
        </RechartsPrimitive.ResponsiveContainer>
      </div>
    </ChartContext.Provider>
  )
})
ChartContainer.displayName = "Chart"

const ChartStyle = ({ id, config }: { id: string; config: ChartConfig }) => {
  const colorConfig = Object.entries(config).filter(
    ([, config]) => config.theme || config.color
  )

  if (!colorConfig.length) {
    return null
  }

  return (
    <style
      dangerouslySetInnerHTML={{
        __html: Object.entries(THEMES)
          .map(
            ([theme, prefix]) => `
${prefix} [data-chart=${id}] {
${colorConfig
  .map(([key, itemConfig]) => {
    const color =
      itemConfig.theme?.[theme as keyof typeof itemConfig.theme] ||
      itemConfig.color
    return color ? `  --color-${key}: ${color};` : null
  })
  .join("\n")}
}
`
          )
          .join("\n"),
      }}
    />
  )
}

const ChartTooltip = RechartsPrimitive.Tooltip

const ChartTooltipContent = React.forwardRef<
  HTMLDivElement,
  React.ComponentProps<typeof RechartsPrimitive.Tooltip> &
    React.ComponentProps<"div"> & {
      hideLabel?: boolean
      hideIndicator?: boolean
      indicator?: "line" | "dot" | "dashed"
      nameKey?: string
      labelKey?: string
    }
>(
  (
    {
      active,
      payload,
      className,
      indicator = "dot",
      hideLabel = false,
      hideIndicator = false,
      label,
      labelFormatter,
      labelClassName,
      formatter,
      color,
      nameKey,
      labelKey,
    },
    ref
  ) => {
    const { config } = useChart()

    const tooltipLabel = React.useMemo(() => {
      if (hideLabel || !payload?.length) {
        return null
      }

      const [item] = payload
      const key = `${labelKey || item?.dataKey || item?.name || "value"}`
      const itemConfig = getPayloadConfigFromPayload(config, item, key)
      const value =
        !labelKey && typeof label === "string"
          ? config[label as keyof typeof config]?.label || label
          : itemConfig?.label

      if (labelFormatter) {
        return (
          <div className={cn("font-medium", labelClassName)}>
            {labelFormatter(value, payload)}
          </div>
        )
      }

      if (!value) {
        return null
      }

      return <div className={cn("font-medium", labelClassName)}>{value}</div>
    }, [
      label,
      labelFormatter,
      payload,
      hideLabel,
      labelClassName,
      config,
      labelKey,
    ])

    if (!active || !payload?.length) {
      return null
    }

    const nestLabel = payload.length === 1 && indicator !== "dot"

    return (
      <div
        ref={ref}
        className={cn(
          "grid min-w-[8rem] items-start gap-1.5 rounded-lg border border-border/50 bg-background px-2.5 py-1.5 text-xs shadow-xl",
          className
        )}
      >
        {!nestLabel ? tooltipLabel : null}
        <div className="grid gap-1.5">
          {payload.map((item, index) => {
            const key = `${nameKey || item.name || item.dataKey || "value"}`
            const itemConfig = getPayloadConfigFromPayload(config, item, key)
            const indicatorColor = color || item.payload.fill || item.color

            return (
              <div
                key={item.dataKey}
                className={cn(
                  "flex w-full flex-wrap items-stretch gap-2 [&>svg]:h-2.5 [&>svg]:w-2.5 [&>svg]:text-muted-foreground",
                  indicator === "dot" && "items-center"
                )}
              >
                {formatter && item?.value !== undefined && item.name ? (
                  formatter(item.value, item.name, item, index, item.payload)
                ) : (
                  <>
                    {itemConfig?.icon ? (
                      <itemConfig.icon />
                    ) : (
                      !hideIndicator && (
                        <div
                          className={cn(
                            "shrink-0 rounded-[2px] border-[--color-border] bg-[--color-bg]",
                            {
                              "h-2.5 w-2.5": indicator === "dot",
                              "w-1": indicator === "line",
                              "w-0 border-[1.5px] border-dashed bg-transparent":
                                indicator === "dashed",
                              "my-0.5": nestLabel && indicator === "dashed",
                            }
                          )}
                          style={
                            {
                              "--color-bg": indicatorColor,
                              "--color-border": indicatorColor,
                            } as React.CSSProperties
                          }
                        />
                      )
                    )}
                    <div
                      className={cn(
                        "flex flex-1 justify-between leading-none",
                        nestLabel ? "items-end" : "items-center"
                      )}
                    >
                      <div className="grid gap-1.5">
                        {nestLabel ? tooltipLabel : null}
                        <span className="text-muted-foreground">
                          {itemConfig?.label || item.name}
                        </span>
                      </div>
                      {item.value && (
                        <span className="font-mono font-medium tabular-nums text-foreground">
                          {item.value.toLocaleString()}
                        </span>
                      )}
                    </div>
                  </>
                )}
              </div>
            )
          })}
        </div>
      </div>
    )
  }
)
ChartTooltipContent.displayName = "ChartTooltip"

const ChartLegend = RechartsPrimitive.Legend

const ChartLegendContent = React.forwardRef<
  HTMLDivElement,
  React.ComponentProps<"div"> &
    Pick<RechartsPrimitive.LegendProps, "payload" | "verticalAlign"> & {
      hideIcon?: boolean
      nameKey?: string
    }
>(
  (
    { className, hideIcon = false, payload, verticalAlign = "bottom", nameKey },
    ref
  ) => {
    const { config } = useChart()

    if (!payload?.length) {
      return null
    }

    return (
      <div
        ref={ref}
        className={cn(
          "flex items-center justify-center gap-4",
          verticalAlign === "top" ? "pb-3" : "pt-3",
          className
        )}
      >
        {payload.map((item) => {
          const key = `${nameKey || item.dataKey || "value"}`
          const itemConfig = getPayloadConfigFromPayload(config, item, key)

          return (
            <div
              key={item.value}
              className={cn(
                "flex items-center gap-1.5 [&>svg]:h-3 [&>svg]:w-3 [&>svg]:text-muted-foreground"
              )}
            >
              {itemConfig?.icon && !hideIcon ? (
                <itemConfig.icon />
              ) : (
                <div
                  className="h-2 w-2 shrink-0 rounded-[2px]"
                  style={{
                    backgroundColor: item.color,
                  }}
                />
              )}
              {itemConfig?.label}
            </div>
          )
        })}
      </div>
    )
  }
)
ChartLegendContent.displayName = "ChartLegend"

// Helper to extract item config from a payload.
function getPayloadConfigFromPayload(
  config: ChartConfig,
  payload: unknown,
  key: string
) {
  if (typeof payload !== "object" || payload === null) {
    return undefined
  }

  const payloadPayload =
    "payload" in payload &&
    typeof payload.payload === "object" &&
    payload.payload !== null
      ? payload.payload
      : undefined

  let configLabelKey: string = key

  if (
    key in payload &&
    typeof payload[key as keyof typeof payload] === "string"
  ) {
    configLabelKey = payload[key as keyof typeof payload] as string
  } else if (
    payloadPayload &&
    key in payloadPayload &&
    typeof payloadPayload[key as keyof typeof payloadPayload] === "string"
  ) {
    configLabelKey = payloadPayload[
      key as keyof typeof payloadPayload
    ] as string
  }

  return configLabelKey in config
    ? config[configLabelKey]
    : config[key as keyof typeof config]
}

export {
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
  ChartLegend,
  ChartLegendContent,
  ChartStyle,
}

client/src/components/global-search.tsx.content:
import { useState, useEffect } from "react";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent } from "@/components/ui/card";
import { Search, X, BookOpen, Heart, Shield, TreePine, Star, Sun } from "lucide-react";
import { chakraData } from "@/lib/chakra-data";
import { lightbodyLayers } from "@/lib/lightbody-data";
import { hovaShields, treeGridSpheres } from "@/lib/spiritual-content";

interface SearchResult {
  id: string;
  title: string;
  description: string;
  category: string;
  type: 'chakra' | 'lightbody' | 'hova' | 'tree-grid' | 'meditation' | 'concept';
  relevance: number;
  path: string;
}

export function GlobalSearch() {
  const [isOpen, setIsOpen] = useState(false);
  const [query, setQuery] = useState("");
  const [results, setResults] = useState<SearchResult[]>([]);
  const [isSearching, setIsSearching] = useState(false);

  // Build searchable content index
  const searchIndex = [
    // Chakras
    ...chakraData.map(chakra => ({
      id: `chakra-${chakra.id}`,
      title: chakra.name,
      description: chakra.description,
      category: chakra.category,
      type: 'chakra' as const,
      content: `${chakra.name} ${chakra.description} ${chakra.function} ${chakra.ascensionPurpose}`,
      path: `/chakras?selected=${chakra.id}`
    })),

    // Lightbody Layers
    ...lightbodyLayers.map(layer => ({
      id: `lightbody-${layer.id}`,
      title: layer.name,
      description: layer.description,
      category: 'lightbody',
      type: 'lightbody' as const,
      content: `${layer.name} ${layer.description} ${layer.function} ${layer.ascensionPurpose}`,
      path: `/lightbody?selected=${layer.id}`
    })),

    // Hova Bodies
    ...hovaShields.map(shield => ({
      id: `hova-${shield.id}`,
      title: shield.name,
      description: shield.description,
      category: 'protection',
      type: 'hova' as const,
      content: `${shield.name} ${shield.description} ${shield.function} ${shield.ascensionPurpose}`,
      path: `/hova-bodies?selected=${shield.id}`
    })),

    // Tree Grid Spheres
    ...treeGridSpheres.map(sphere => ({
      id: `tree-${sphere.id}`,
      title: `Sphere ${sphere.id}: ${sphere.name}`,
      description: sphere.function,
      category: 'tree-grid',
      type: 'tree-grid' as const,
      content: `${sphere.name} ${sphere.function} ${sphere.dimension}`,
      path: `/tree-grid?selected=${sphere.id}`
    })),

    // Meditation concepts
    {
      id: 'meditation-12d-shield',
      title: '12D Shield Protection',
      description: 'Foundational protection practice for spiritual work',
      category: 'meditation',
      type: 'meditation' as const,
      content: '12D Shield protection spiritual safety Christ consciousness',
      path: '/meditation'
    },
    {
      id: 'meditation-ra-center',
      title: 'RA Center Activation',
      description: 'Solar hub activation for cosmic timeline alignment',
      category: 'meditation',
      type: 'meditation' as const,
      content: 'RA Center solar hub plasma rivers golden sphere',
      path: '/soul-codex'
    }
  ];

  // Search function with relevance scoring
  const performSearch = (searchQuery: string) => {
    if (!searchQuery.trim()) {
      setResults([]);
      return;
    }

    setIsSearching(true);

    const searchTerms = searchQuery.toLowerCase().split(' ');
    const searchResults: SearchResult[] = [];

    searchIndex.forEach(item => {
      let relevance = 0;
      const searchableText = item.content.toLowerCase();

      // Title exact match gets highest score
      if (item.title.toLowerCase().includes(searchQuery.toLowerCase())) {
        relevance += 100;
      }

      // Each search term match in content
      searchTerms.forEach(term => {
        if (term.length > 2) {
          const matches = (searchableText.match(new RegExp(term, 'g')) || []).length;
          relevance += matches * 10;
        }
      });

      // Category relevance boost
      if (item.category.toLowerCase().includes(searchQuery.toLowerCase())) {
        relevance += 20;
      }

      if (relevance > 0) {
        searchResults.push({
          id: item.id,
          title: item.title,
          description: item.description,
          category: item.category,
          type: item.type,
          relevance,
          path: item.path
        });
      }
    });

    // Sort by relevance
    searchResults.sort((a, b) => b.relevance - a.relevance);
    setResults(searchResults.slice(0, 10)); // Top 10 results
    setIsSearching(false);
  };

  // Debounced search
  useEffect(() => {
    const timeoutId = setTimeout(() => {
      performSearch(query);
    }, 300);

    return () => clearTimeout(timeoutId);
  }, [query]);

  // Keyboard shortcut
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
        e.preventDefault();
        setIsOpen(true);
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, []);

  const getTypeIcon = (type: string) => {
    switch (type) {
      case 'chakra': return <Heart className="w-4 h-4" />;
      case 'lightbody': return <Star className="w-4 h-4" />;
      case 'hova': return <Shield className="w-4 h-4" />;
      case 'tree-grid': return <TreePine className="w-4 h-4" />;
      case 'meditation': return <Sun className="w-4 h-4" />;
      default: return <BookOpen className="w-4 h-4" />;
    }
  };

  const getCategoryColor = (category: string) => {
    const colors = {
      physical: 'bg-red-500/20 text-red-400',
      morphogenetic: 'bg-purple-500/20 text-purple-400',
      avatar: 'bg-gold-500/20 text-gold-400',
      lightbody: 'bg-blue-500/20 text-blue-400',
      protection: 'bg-green-500/20 text-green-400',
      'tree-grid': 'bg-indigo-500/20 text-indigo-400',
      meditation: 'bg-orange-500/20 text-orange-400'
    };
    return colors[category as keyof typeof colors] || 'bg-cosmic-500/20 text-cosmic-400';
  };

  return (
    <Dialog open={isOpen} onOpenChange={setIsOpen}>
      <DialogTrigger asChild>
        <Button
          variant="outline"
          className="relative h-9 w-9 p-0 xl:h-10 xl:w-60 xl:justify-start xl:px-3 xl:py-2 border-cosmic-600 text-cosmic-300 hover:bg-cosmic-700"
        >
          <Search className="h-4 w-4 xl:mr-2" />
          <span className="hidden xl:inline-flex">Search spiritual content...</span>
          <kbd className="pointer-events-none absolute right-1.5 top-2 hidden h-6 select-none items-center gap-1 rounded border border-cosmic-600 bg-cosmic-800 px-1.5 font-mono text-[10px] font-medium text-cosmic-400 xl:flex">
            <span className="text-xs">⌘</span>K
          </kbd>
        </Button>
      </DialogTrigger>
      <DialogContent className="max-w-2xl max-h-[80vh] overflow-hidden p-0" aria-describedby="search-dialog-description">
        <DialogHeader className="p-6 pb-0">
          <DialogTitle className="text-xl font-sacred text-sacred-gold">
            Search Spiritual Content
          </DialogTitle>
          <div className="sr-only">
            <p id="search-dialog-description">Search through chakras, lightbody layers, spiritual concepts, and meditation content</p>
          </div>
        </DialogHeader>

        <div className="p-6 pt-3">
          <div className="relative">
            <Search className="absolute left-3 top-3 h-4 w-4 text-cosmic-400" />
            <Input
              placeholder="Search chakras, lightbody, meditations..."
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              className="pl-10 bg-cosmic-800 border-cosmic-600 text-white placeholder-cosmic-400"
              autoFocus
            />
            {query && (
              <Button
                variant="ghost"
                size="sm"
                className="absolute right-1 top-1 h-8 w-8 p-0"
                onClick={() => setQuery("")}
              >
                <X className="h-4 w-4" />
              </Button>
            )}
          </div>
        </div>

        <div className="max-h-96 overflow-y-auto px-6 pb-6">
          {isSearching ? (
            <div className="text-center py-8 text-cosmic-300">
              <div className="animate-spin w-6 h-6 border-2 border-sacred-gold border-t-transparent rounded-full mx-auto mb-2"></div>
              Searching...
            </div>
          ) : results.length > 0 ? (
            <div className="space-y-3">
              {results.map((result) => (
                <Card
                  key={result.id}
                  className="sacred-card cursor-pointer hover:border-sacred-gold/40 transition-all duration-300"
                  onClick={() => {
                    window.location.href = result.path;
                    setIsOpen(false);
                  }}
                >
                  <CardContent className="p-4">
                    <div className="flex items-start justify-between">
                      <div className="flex items-start space-x-3 flex-1">
                        <div className="mt-0.5">
                          {getTypeIcon(result.type)}
                        </div>
                        <div className="flex-1 min-w-0">
                          <h3 className="font-semibold text-white text-sm truncate">
                            {result.title}
                          </h3>
                          <p className="text-cosmic-300 text-xs mt-1 line-clamp-2">
                            {result.description}
                          </p>
                        </div>
                      </div>
                      <Badge variant="outline" className={`ml-2 text-xs ${getCategoryColor(result.category)}`}>
                        {result.category}
                      </Badge>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          ) : query ? (
            <div className="text-center py-8 text-cosmic-300">
              <Search className="w-12 h-12 mx-auto mb-4 opacity-50" />
              <p>No results found for "{query}"</p>
              <p className="text-sm mt-2">Try searching for chakras, lightbody, meditations, or spiritual concepts</p>
            </div>
          ) : (
            <div className="text-center py-8 text-cosmic-300">
              <Search className="w-12 h-12 mx-auto mb-4 opacity-50" />
              <p>Start typing to search spiritual content</p>
              <div className="grid grid-cols-2 gap-2 mt-4 text-xs">
                <div>• Chakra systems</div>
                <div>• Lightbody layers</div>
                <div>• Protection practices</div>
                <div>• Tree Grid spheres</div>
              </div>
            </div>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

