import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { 
  Moon, 
  Sun, 
  Globe, 
  Clock, 
  Zap,
  Sparkles,
  Calendar,
  MapPin,
  Loader2
} from 'lucide-react';
import { AstronomyService, WeatherService, MeditationTimingService } from '@/lib/api-services';
import type { AstronomyData, WeatherData, MeditationTiming } from '@/lib/api-services';

export function PlanetaryGridMonitor() {
  const [astronomyData, setAstronomyData] = useState<AstronomyData | null>(null);
  const [weatherData, setWeatherData] = useState<WeatherData | null>(null);
  const [meditationTiming, setMeditationTiming] = useState<MeditationTiming | null>(null);
  const [loading, setLoading] = useState(true);
  const [location, setLocation] = useState<{ lat: number; lon: number } | null>(null);
  const [lastUpdate, setLastUpdate] = useState<Date>(new Date());

  useEffect(() => {
    loadPlanetaryData();
    const interval = setInterval(loadPlanetaryData, 300000); // Update every 5 minutes
    return () => clearInterval(interval);
  }, []);

  const loadPlanetaryData = async () => {
    setLoading(true);
    try {
      // Get user location
      const coords = await getUserLocation();
      setLocation(coords);

      // Load all data simultaneously
      const [astronomy, weather, timing] = await Promise.all([
        AstronomyService.getCurrentAstronomyData(coords?.lat, coords?.lon),
        WeatherService.getWeatherForMeditation(coords?.lat, coords?.lon),
        MeditationTimingService.getOptimalMeditationTime(coords?.lat, coords?.lon)
      ]);

      setAstronomyData(astronomy);
      setWeatherData(weather);
      setMeditationTiming(timing);
      setLastUpdate(new Date());
    } catch (error) {
      console.error('Error loading planetary data:', error);
    } finally {
      setLoading(false);
    }
  };

  const getUserLocation = (): Promise<{ lat: number; lon: number } | null> => {
    return new Promise((resolve) => {
      if ('geolocation' in navigator) {
        navigator.geolocation.getCurrentPosition(
          (position) => {
            resolve({
              lat: position.coords.latitude,
              lon: position.coords.longitude
            });
          },
          () => resolve(null),
          { timeout: 5000 }
        );
      } else {
        resolve(null);
      }
    });
  };

  const getMoonPhaseIcon = (phase: string) => {
    const phases = {
      'New Moon': '🌑',
      'Waxing Crescent': '🌒',
      'First Quarter': '🌓',
      'Waxing Gibbous': '🌔',
      'Full Moon': '🌕',
      'Waning Gibbous': '🌖',
      'Last Quarter': '🌗',
      'Waning Crescent': '🌘'
    };
    return phases[phase] || '🌙';
  };

  const getOptimalityColor = (optimal: boolean) => 
    optimal ? 'text-green-400' : 'text-yellow-400';

  if (loading) {
    return (
      <Card className="sacred-card">
        <CardContent className="flex items-center justify-center p-8">
          <div className="text-center">
            <Loader2 className="w-8 h-8 animate-spin text-sacred-gold mx-auto mb-4" />
            <p className="text-cosmic-300">Loading planetary conditions...</p>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <Card className="sacred-card">
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle className="text-xl font-sacred text-sacred-gold flex items-center">
              <Globe className="w-6 h-6 mr-2" />
              Planetary Grid Monitor
            </CardTitle>
            <Button 
              onClick={loadPlanetaryData}
              variant="outline"
              size="sm"
              className="border-cosmic-600 text-cosmic-300 hover:bg-cosmic-700"
            >
              <Zap className="w-4 h-4 mr-2" />
              Refresh
            </Button>
          </div>
          <p className="text-cosmic-400 text-sm">
            Real-time planetary conditions for optimal spiritual practice
          </p>
        </CardHeader>
      </Card>

      {/* Current Conditions Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">

        {/* Lunar Information */}
        <Card className="sacred-card">
          <CardHeader>
            <CardTitle className="text-lg font-sacred text-sacred-gold flex items-center">
              <Moon className="w-5 h-5 mr-2" />
              Lunar Conditions
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            {astronomyData && (
              <>
                <div className="flex items-center justify-between">
                  <span className="text-cosmic-300">Phase:</span>
                  <div className="flex items-center gap-2">
                    <span className="text-2xl">{getMoonPhaseIcon(astronomyData.moonPhase)}</span>
                    <span className="text-white">{astronomyData.moonPhase}</span>
                  </div>
                </div>

                <div className="flex items-center justify-between">
                  <span className="text-cosmic-300">Illumination:</span>
                  <span className="text-white">
                    {Math.round(astronomyData.moonIllumination * 100)}%
                  </span>
                </div>

                <div className="bg-cosmic-800/30 rounded-lg p-3">
                  <p className="text-xs text-cosmic-400 mb-2">Lunar Energy Guidance:</p>
                  <p className="text-sm text-cosmic-200">
                    {astronomyData.moonPhase === 'New Moon' && 
                      'Perfect for new intentions and inner reflection'}
                    {astronomyData.moonPhase === 'Full Moon' && 
                      'Ideal for manifestation and energy clearing'}
                    {astronomyData.moonPhase.includes('Waxing') && 
                      'Building energy - focus on growth and expansion'}
                    {astronomyData.moonPhase.includes('Waning') && 
                      'Releasing energy - time for letting go and cleansing'}
                    {!astronomyData.moonPhase.includes('New') && 
                     !astronomyData.moonPhase.includes('Full') &&
                     !astronomyData.moonPhase.includes('Waxing') &&
                     !astronomyData.moonPhase.includes('Waning') &&
                      'Balanced lunar energy for general spiritual practice'}
                  </p>
                </div>
              </>
            )}
          </CardContent>
        </Card>

        {/* Solar Information */}
        <Card className="sacred-card">
          <CardHeader>
            <CardTitle className="text-lg font-sacred text-sacred-gold flex items-center">
              <Sun className="w-5 h-5 mr-2" />
              Solar Conditions
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            {astronomyData && (
              <>
                <div className="flex items-center justify-between">
                  <span className="text-cosmic-300">Sunrise:</span>
                  <span className="text-white">{astronomyData.sunrise}</span>
                </div>

                <div className="flex items-center justify-between">
                  <span className="text-cosmic-300">Sunset:</span>
                  <span className="text-white">{astronomyData.sunset}</span>
                </div>

                <div className="bg-cosmic-800/30 rounded-lg p-3">
                  <p className="text-xs text-cosmic-400 mb-2">Solar Energy Guidance:</p>
                  <p className="text-sm text-cosmic-200">
                    Dawn and dusk are optimal for spiritual practice. 
                    Solar energy supports active meditation and chakra work.
                  </p>
                </div>
              </>
            )}
          </CardContent>
        </Card>

        {/* Weather Conditions */}
        <Card className="sacred-card">
          <CardHeader>
            <CardTitle className="text-lg font-sacred text-sacred-gold flex items-center">
              <Globe className="w-5 h-5 mr-2" />
              Atmospheric Conditions
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            {weatherData && (
              <>
                <div className="flex items-center justify-between">
                  <span className="text-cosmic-300">Condition:</span>
                  <Badge variant="outline" className="border-cosmic-600 text-cosmic-200">
                    {weatherData.condition}
                  </Badge>
                </div>

                <div className="flex items-center justify-between">
                  <span className="text-cosmic-300">Temperature:</span>
                  <span className="text-white">{weatherData.temperature}°C</span>
                </div>

                <div className="bg-cosmic-800/30 rounded-lg p-3">
                  <p className="text-xs text-cosmic-400 mb-2">Practice Recommendation:</p>
                  <p className="text-sm text-cosmic-200">
                    {weatherData.recommendation}
                  </p>
                </div>
              </>
            )}
          </CardContent>
        </Card>
      </div>

      {/* Meditation Timing Optimization */}
      <Card className="sacred-card">
        <CardHeader>
          <CardTitle className="text-lg font-sacred text-sacred-gold flex items-center">
            <Clock className="w-5 h-5 mr-2" />
            Meditation Timing Analysis
          </CardTitle>
        </CardHeader>
        <CardContent>
          {meditationTiming && (
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <span className="text-cosmic-300">Current Conditions:</span>
                <Badge 
                  variant={meditationTiming.optimal ? "default" : "outline"}
                  className={`${meditationTiming.optimal ? 'bg-green-600' : 'border-yellow-600 text-yellow-400'}`}
                >
                  <Sparkles className="w-3 h-3 mr-1" />
                  {meditationTiming.optimal ? 'Optimal' : 'Good'}
                </Badge>
              </div>

              <div className="bg-cosmic-800/30 rounded-lg p-4">
                <p className="text-sm font-medium text-sacred-gold mb-3">
                  {meditationTiming.recommendation}
                </p>

                <div className="space-y-2">
                  <p className="text-xs text-cosmic-400 mb-2">Contributing Factors:</p>
                  {meditationTiming.factors.map((factor, index) => (
                    <div key={index} className="flex items-start gap-2">
                      <div className="w-1.5 h-1.5 rounded-full bg-sacred-gold mt-2 flex-shrink-0"></div>
                      <span className="text-sm text-cosmic-200">{factor}</span>
                    </div>
                  ))}
                </div>
              </div>

              <div className="flex items-center justify-between text-sm">
                <span className="text-cosmic-400">Next Optimal Time:</span>
                <span className="text-cosmic-200">{meditationTiming.nextOptimal}</span>
              </div>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Planetary Positions */}
      {astronomyData?.planetaryPositions && (
        <Card className="sacred-card">
          <CardHeader>
            <CardTitle className="text-lg font-sacred text-sacred-gold flex items-center">
              <Calendar className="w-5 h-5 mr-2" />
              Planetary Positions
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-4">
              {Object.entries(astronomyData.planetaryPositions).map(([planet, position]) => (
                <div key={planet} className="bg-cosmic-800/30 rounded-lg p-3 text-center">
                  <p className="font-medium text-white mb-1">{planet}</p>
                  <p className="text-sm text-cosmic-300">{position.sign}</p>
                  <p className="text-xs text-cosmic-400">{position.degree}°</p>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Status Footer */}
      <div className="flex items-center justify-between text-sm text-cosmic-400">
        <div className="flex items-center gap-2">
          <MapPin className="w-4 h-4" />
          <span>
            {location ? 
              `${location.lat.toFixed(2)}, ${location.lon.toFixed(2)}` : 
              'Location not available'
            }
          </span>
        </div>
        <span>Last updated: {lastUpdate.toLocaleTimeString()}</span>
      </div>
    </div>
  );
}

