                        />
                        <div>
                          <h3 className="font-semibold text-white">{layer.name}</h3>
                          <div className="text-sm text-cosmic-300">
                            {layer.frequency.toFixed(1)} Hz • {layer.thickness.toFixed(1)}cm thick
