                      className={`cursor-pointer transition-all duration-300 hover:scale-105 ${
                        currentPreset.id === preset.id && !useCustom
                          ? 'ring-2 ring-sacred-gold bg-cosmic-800'
                          : 'hover:bg-cosmic-800'
                      }`}
                      onClick={() => {
                        setCurrentPreset(preset);
                        setUseCustom(false);
