client/src/components/diagrams/universal.content:
import { motion } from "framer-motion";
import { useState } from "react";

interface UTMDiagramProps {
  selectedHU?: string | null;
  onHUSelect?: (huId: string) => void;
  interactive?: boolean;
  className?: string;
}

// Authentic Universal Time Matrix structure based on ES teachings
const harmonicUniverses = [
  {
    id: 'hu1',
    name: 'HU-1 (Matter Universe)',
    dimensions: ['1D Physical', '2D Emotional', '3D Mental'],
    colors: ['#cc0000', '#ff6600', '#ffdd33'],
    position: { x: 50, y: 85 },
    description: 'Dense matter reality, 3D Earth experience'
  },
  {
    id: 'hu2', 
    name: 'HU-2 (Anti-Matter Universe)',
    dimensions: ['4D Astral', '5D Archetypal', '6D Celestial'],
    colors: ['#ff66cc', '#ff9933', '#33ff66'],
    position: { x: 50, y: 65 },
    description: 'Soul matrix, astral planes, archetypal realms'
  },
  {
    id: 'hu3',
    name: 'HU-3 (Light Matter Universe)', 
    dimensions: ['7D Mental', '8D Monadic', '9D Avatar'],
    colors: ['#ffdd33', '#c7a2ff', '#3366ff'],
    position: { x: 50, y: 45 },
    description: 'Monad matrix, lightbody activation, avatar consciousness'
  },
  {
    id: 'hu4',
    name: 'HU-4 (Liquid Light Universe)',
    dimensions: ['10D Avatar', '11D Monadic', '12D Christ'],
    colors: ['#9966ff', '#c7a2ff', '#ffffff'],
    position: { x: 50, y: 25 },
    description: 'Avatar matrix, Christ consciousness, liquid light body'
  },
  {
    id: 'hu5',
    name: 'HU-5 (Plasma Light Universe)',
    dimensions: ['13D Mother Arc', '14D Solar', '15D Universal'],
    colors: ['#66ffff', '#ffdd77', '#ffffff'],
    position: { x: 50, y: 8 },
    description: 'Founder matrix, plasma light body, universal consciousness'
  }
];

const densityLevels = [
  { name: 'Density 1', dimensions: [1, 2, 3], color: '#ff4444' },
  { name: 'Density 2', dimensions: [4, 5, 6], color: '#44ff44' },
  { name: 'Density 3', dimensions: [7, 8, 9], color: '#4444ff' },
  { name: 'Density 4', dimensions: [10, 11, 12], color: '#ffff44' },
  { name: 'Density 5', dimensions: [13, 14, 15], color: '#ff44ff' }
];

export function UTMDiagram({ 
  selectedHU, 
  onHUSelect, 
  interactive = true,
  className = ""
}: UTMDiagramProps) {
  const [hoveredHU, setHoveredHU] = useState<string | null>(null);

  return (
    <div className={`w-full space-y-6 ${className}`}>
      {/* Main UTM Diagram */}
      <div className="relative bg-gradient-to-b from-cosmic-900 to-cosmic-950 rounded-lg p-6 min-h-[500px]">
        <svg
          viewBox="0 0 100 100"
          className="w-full h-full"
          style={{ minHeight: '400px' }}
        >
          <defs>
            {/* Gradient definitions for each HU */}
            {harmonicUniverses.map((hu, index) => (
              <radialGradient key={`grad-${hu.id}`} id={`gradient-${hu.id}`} cx="50%" cy="50%">
                <stop offset="0%" stopColor={hu.colors[0]} stopOpacity="0.8" />
                <stop offset="50%" stopColor={hu.colors[1]} stopOpacity="0.6" />
                <stop offset="100%" stopColor={hu.colors[2]} stopOpacity="0.4" />
              </radialGradient>
            ))}

            <filter id="glow">
              <feGaussianBlur stdDeviation="2" result="coloredBlur"/>
              <feMerge> 
                <feMergeNode in="coloredBlur"/>
                <feMergeNode in="SourceGraphic"/>
              </feMerge>
            </filter>
          </defs>

          {/* Vertical axis - evolutionary progression */}
          <line 
            x1="50" y1="5" 
            x2="50" y2="95" 
            stroke="rgba(255,215,0,0.4)" 
            strokeWidth="0.3" 
            strokeDasharray="1,1"
          />

          {/* Harmonic Universe spheres */}
          {harmonicUniverses.map((hu, index) => (
            <g key={hu.id}>
              {/* HU container sphere */}
              <motion.ellipse
                cx={hu.position.x}
                cy={hu.position.y}
                rx="18"
                ry="8"
                fill={`url(#gradient-${hu.id})`}
                stroke={hoveredHU === hu.id ? '#ffffff' : hu.colors[1]}
                strokeWidth={hoveredHU === hu.id ? "0.3" : "0.2"}
                filter="url(#glow)"
                className={interactive ? "cursor-pointer" : ""}
                onClick={() => interactive && onHUSelect?.(hu.id)}
                onMouseEnter={() => setHoveredHU(hu.id)}
                onMouseLeave={() => setHoveredHU(null)}
                animate={{ 
                  scale: hoveredHU === hu.id ? 1.1 : 1,
                  opacity: selectedHU === hu.id ? 1 : 0.8
                }}
                transition={{ duration: 0.3 }}
              />

              {/* Individual dimension points within each HU */}
              {hu.dimensions.map((dim, dimIndex) => (
                <motion.circle
                  key={`${hu.id}-${dimIndex}`}
                  cx={hu.position.x + (dimIndex - 1) * 6}
                  cy={hu.position.y}
                  r="1.5"
                  fill={hu.colors[dimIndex]}
                  stroke="rgba(255,255,255,0.6)"
                  strokeWidth="0.1"
                  animate={{ 
                    scale: [1, 1.2, 1],
                    opacity: [0.7, 1, 0.7]
                  }}
                  transition={{ 
                    duration: 2,
                    repeat: Infinity,
                    delay: index * 0.2 + dimIndex * 0.1
                  }}
                />
              ))}

              {/* HU labels */}
              <text
                x={hu.position.x + 20}
                y={hu.position.y + 1}
                fill="rgba(255,255,255,0.9)"
                fontSize="2.5"
                textAnchor="start"
                className="font-medium"
              >
                {hu.name.split('(')[0]}
              </text>

              {/* Dimension labels */}
              <text
                x={hu.position.x + 20}
                y={hu.position.y + 4}
                fill="rgba(255,255,255,0.7)"
                fontSize="1.5"
                textAnchor="start"
              >
                {hu.dimensions.join(' • ')}
              </text>
            </g>
          ))}

          {/* Dimensional bridges between HUs */}
          {harmonicUniverses.slice(0, -1).map((hu, index) => (
            <motion.line
              key={`bridge-${index}`}
              x1={hu.position.x}
              y1={hu.position.y - 5}
              x2={harmonicUniverses[index + 1].position.x}
              y2={harmonicUniverses[index + 1].position.y + 5}
              stroke="rgba(255,215,0,0.6)"
              strokeWidth="0.2"
              strokeDasharray="2,2"
              animate={{ strokeDashoffset: [0, 4] }}
              transition={{ duration: 3, repeat: Infinity, ease: "linear" }}
            />
          ))}

          {/* Density level indicators on the right */}
          {densityLevels.map((density, index) => (
            <g key={`density-${index}`}>
              <rect
                x="85"
                y={85 - index * 20}
                width="12"
                height="15"
                fill={density.color}
                opacity="0.3"
                rx="2"
              />
              <text
                x="91"
                y={93 - index * 20}
                fill="rgba(255,255,255,0.8)"
                fontSize="1.5"
                textAnchor="middle"
              >
                D{index + 1}
              </text>
            </g>
          ))}
        </svg>

        {/* Legend */}
        <div className="absolute top-4 left-4 bg-cosmic-900/80 rounded-lg p-3 text-xs">
          <h4 className="text-white font-semibold mb-2">Universal Time Matrix</h4>
          <div className="space-y-1 text-cosmic-200">
            <div>• 5 Harmonic Universes</div>
            <div>• 15 Dimensional Levels</div>
            <div>• 5 Density Planes</div>
            <div>• Consciousness Evolution Path</div>
          </div>
        </div>
      </div>

      {/* HU Information Panel */}
      {selectedHU && (
        <div className="bg-cosmic-900/50 rounded-lg p-4">
          {(() => {
            const hu = harmonicUniverses.find(h => h.id === selectedHU);
            return hu ? (
              <div>
                <h3 className="text-lg font-semibold text-white mb-2">{hu.name}</h3>
                <p className="text-cosmic-200 mb-3">{hu.description}</p>
                <div className="grid grid-cols-3 gap-2">
                  {hu.dimensions.map((dim, index) => (
                    <div key={index} className="text-center p-2 bg-cosmic-800/50 rounded">
                      <div 
                        className="w-4 h-4 rounded-full mx-auto mb-1"
                        style={{ backgroundColor: hu.colors[index] }}
                      />
                      <div className="text-xs text-white">{dim}</div>
                    </div>
                  ))}
                </div>
              </div>
            ) : null;
          })()}
        </div>
      )}

      {/* Interactive Controls */}
      {interactive && (
        <div className="flex justify-center space-x-2">
          {harmonicUniverses.map((hu, index) => (
            <button
              key={hu.id}
              onClick={() => onHUSelect?.(hu.id)}
              className={`px-3 py-1 rounded text-xs transition-colors ${
                selectedHU === hu.id 
                  ? 'bg-cosmic-600 text-white' 
                  : 'bg-cosmic-800 text-cosmic-300 hover:bg-cosmic-700'
              }`}
            >
              HU-{index + 1}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

export { UTMDiagram as UniversalTimeMatrixDiagram };

