import { useState } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";

interface TreeGridDiagramProps {
  selectedSphere?: string | null;
  onSphereSelect?: (sphereId: string) => void;
  showPaths?: boolean;
  interactive?: boolean;
}

// Authentic Kathara Grid sphere positions based on ES teachings
const treeGridSpheres = [
  { id: 'kathara-12', name: 'Kee-Ra-ShA', position: { x: 50, y: 8 }, color: '#ffffff', dimension: 12, description: 'Avatar Matrix - Unity Consciousness' },
  { id: 'kathara-11', name: 'Khem', position: { x: 35, y: 18 }, color: '#c7a2ff', dimension: 11, description: 'Monad Matrix - Divine Wisdom' },
  { id: 'kathara-10', name: 'Khen', position: { x: 65, y: 18 }, color: '#9966ff', dimension: 10, description: 'Avatar Matrix - Understanding' },
  { id: 'kathara-9', name: 'Khundaray', position: { x: 35, y: 32 }, color: '#3366ff', dimension: 9, description: 'Soul Matrix - Magnetic Force' },
  { id: 'kathara-8', name: 'Khundra', position: { x: 65, y: 32 }, color: '#ff3366', dimension: 8, description: 'Soul Matrix - Electrical Force' },
  { id: 'kathara-7', name: 'Ka-Le-Ah', position: { x: 50, y: 42 }, color: '#ffdd33', dimension: 7, description: 'Mental Matrix - Christ Consciousness' },
  { id: 'kathara-6', name: 'Shara', position: { x: 35, y: 58 }, color: '#33ff66', dimension: 6, description: 'Emotional Matrix - Celestial Mind' },
  { id: 'kathara-5', name: 'Shala', position: { x: 65, y: 58 }, color: '#ff9933', dimension: 5, description: 'Emotional Matrix - Archetypal Mind' },
  { id: 'kathara-4', name: 'Rasha', position: { x: 50, y: 72 }, color: '#ff66cc', dimension: 4, description: 'Astral Matrix - Doradic Shield' },
  { id: 'kathara-3', name: 'Jha-FA', position: { x: 50, y: 85 }, color: '#996633', dimension: 3, description: 'Physical Matrix - Telluric Shield' },
  { id: 'kathara-2', name: 'Jha-Da', position: { x: 30, y: 85 }, color: '#ff6600', dimension: 2, description: 'Etheric Matrix - Instinctual Mind' },
  { id: 'kathara-1', name: 'Jha', position: { x: 70, y: 85 }, color: '#cc0000', dimension: 1, description: 'Physical Matrix - Base Consciousness' }
];

// Authentic Kathara Grid connections based on ES teachings
const treeGridPaths = [
  // Primary Triad Connections
  { from: 'kathara-12', to: 'kathara-11', name: 'Avatar Bridge' },
  { from: 'kathara-12', to: 'kathara-10', name: 'Avatar Bridge' },
  { from: 'kathara-11', to: 'kathara-10', name: 'Avatar Triangle' },

  // Secondary Triad Connections  
  { from: 'kathara-11', to: 'kathara-9', name: 'Soul Bridge' },
  { from: 'kathara-10', to: 'kathara-8', name: 'Soul Bridge' },
  { from: 'kathara-9', to: 'kathara-8', name: 'Soul Triangle' },

  // Central Heart Connections
  { from: 'kathara-12', to: 'kathara-7', name: 'Divine Heart Channel' },
  { from: 'kathara-9', to: 'kathara-7', name: 'Magnetic Heart' },
  { from: 'kathara-8', to: 'kathara-7', name: 'Electrical Heart' },

  // Mental-Emotional Bridge
  { from: 'kathara-7', to: 'kathara-6', name: 'Mental-Emotional Bridge' },
  { from: 'kathara-7', to: 'kathara-5', name: 'Mental-Emotional Bridge' },
  { from: 'kathara-6', to: 'kathara-5', name: 'Emotional Triangle' },

  // Astral Connections
  { from: 'kathara-7', to: 'kathara-4', name: 'Heart-Astral Channel' },
  { from: 'kathara-6', to: 'kathara-4', name: 'Emotional-Astral' },
  { from: 'kathara-5', to: 'kathara-4', name: 'Mental-Astral' },

  // Physical Matrix
  { from: 'kathara-4', to: 'kathara-3', name: 'Astral-Physical Bridge' },
  { from: 'kathara-3', to: 'kathara-2', name: 'Physical Triangle' },
  { from: 'kathara-3', to: 'kathara-1', name: 'Physical Triangle' },
  { from: 'kathara-2', to: 'kathara-1', name: 'Base Triangle' },

  // Vertical Channels
  { from: 'kathara-11', to: 'kathara-6', name: 'Left Pillar' },
  { from: 'kathara-6', to: 'kathara-2', name: 'Left Pillar' },
  { from: 'kathara-10', to: 'kathara-5', name: 'Right Pillar' },
  { from: 'kathara-5', to: 'kathara-1', name: 'Right Pillar' }
];

export function TreeGridDiagram({ 
  selectedSphere, 
  onSphereSelect, 
  showPaths = true, 
  interactive = true 
}: TreeGridDiagramProps) {
  const [hoveredSphere, setHoveredSphere] = useState<string | null>(null);

  const isActive = (sphereId: string) => {
    return selectedSphere === sphereId || hoveredSphere === sphereId;
  };

  const getSphereById = (id: string) => {
    return treeGridSpheres.find(s => s.id === id);
  };

  return (
    <div className="relative w-full max-w-lg mx-auto">
      {/* SVG Tree of Life Diagram */}
      <svg
        viewBox="0 0 100 100"
        className="w-full h-auto"
        style={{ aspectRatio: '3/4' }}
      >
        {/* Background sacred geometry */}
        <defs>
          <radialGradient id="sphereGradient" cx="30%" cy="30%">
            <stop offset="0%" stopColor="rgba(255,255,255,0.3)" />
            <stop offset="100%" stopColor="rgba(255,255,255,0.1)" />
          </radialGradient>
          <filter id="glow">
            <feGaussianBlur stdDeviation="2" result="coloredBlur"/>
            <feMerge> 
              <feMergeNode in="coloredBlur"/>
              <feMergeNode in="SourceGraphic"/>
            </feMerge>
          </filter>
        </defs>

        {/* Paths between spheres */}
        {showPaths && treeGridPaths.map((path, index) => {
          const fromSphere = getSphereById(path.from);
          const toSphere = getSphereById(path.to);
          if (!fromSphere || !toSphere) return null;

          const isPathActive = isActive(path.from) || isActive(path.to);

          return (
            <line
              key={`path-${index}`}
              x1={fromSphere.position.x}
              y1={fromSphere.position.y}
              x2={toSphere.position.x}
              y2={toSphere.position.y}
              stroke={isPathActive ? "rgba(255, 255, 255, 0.6)" : "rgba(255, 255, 255, 0.2)"}
              strokeWidth={isPathActive ? "0.5" : "0.3"}
              className="transition-all duration-300"
            />
          );
        })}

        {/* Tree spheres */}
        {treeGridSpheres.map((sphere) => {
          const active = isActive(sphere.id);
          const radius = active ? 4.5 : 3.5;

          return (
            <g key={sphere.id}>
              {/* Sphere glow effect */}
              {active && (
                <circle
                  cx={sphere.position.x}
                  cy={sphere.position.y}
                  r={radius * 1.8}
                  fill={sphere.color}
                  opacity="0.2"
                  className="animate-pulse"
                  filter="url(#glow)"
                />
              )}

              {/* Main sphere */}
              <circle
                cx={sphere.position.x}
                cy={sphere.position.y}
                r={radius}
                fill={sphere.color}
                stroke={active ? "#ffffff" : "rgba(255, 255, 255, 0.4)"}
                strokeWidth={active ? "0.8" : "0.3"}
                className={`transition-all duration-300 ${
                  interactive ? 'cursor-pointer hover:opacity-80' : ''
                }`}
                onClick={() => interactive && onSphereSelect?.(sphere.id)}
                onMouseEnter={() => interactive && setHoveredSphere(sphere.id)}
                onMouseLeave={() => interactive && setHoveredSphere(null)}
                style={{ filter: 'url(#sphereGradient)' }}
              />

              {/* Inner sacred symbol */}
              <circle
                cx={sphere.position.x}
                cy={sphere.position.y}
                r={radius * 0.3}
                fill="none"
                stroke="rgba(255, 255, 255, 0.8)"
                strokeWidth="0.2"
                className={active ? 'animate-spin' : ''}
                style={{ 
                  animationDuration: active ? '12s' : '0s',
                  animationDirection: 'normal'
                }}
              />

              {/* Sphere labels */}
              {active && (
                <g>
                  <text
                    x={sphere.position.x}
                    y={sphere.position.y - 6}
                    fill="#ffffff"
                    fontSize="2.5"
                    fontWeight="bold"
                    textAnchor="middle"
                    className="drop-shadow-lg"
                  >
                    {sphere.name}
                  </text>
                  <text
                    x={sphere.position.x}
                    y={sphere.position.y + 8}
                    fill={sphere.color}
                    fontSize="1.8"
                    textAnchor="middle"
                    className="drop-shadow-sm"
                  >
                    {sphere.dimension}D
                  </text>
                </g>
              )}
            </g>
          );
        })}

        {/* Three Kathara Pillars */}
        <g opacity="0.4">
          {/* Left Pillar - Magnetic/Feminine */}
          <line x1="35" y1="15" x2="35" y2="88" stroke="#ff3366" strokeWidth="0.3" strokeDasharray="2,2" />
          <text x="28" y="12" fill="#ff3366" fontSize="1.8" textAnchor="middle">Magnetic</text>

          {/* Central Pillar - Christ Consciousness */}
          <line x1="50" y1="5" x2="50" y2="88" stroke="#ffdd33" strokeWidth="0.4" strokeDasharray="3,1" />
          <text x="50" y="5" fill="#ffdd33" fontSize="1.8" textAnchor="middle">Christ</text>

          {/* Right Pillar - Electrical/Masculine */}
          <line x1="65" y1="15" x2="65" y2="88" stroke="#3366ff" strokeWidth="0.3" strokeDasharray="2,2" />
          <text x="72" y="12" fill="#3366ff" fontSize="1.8" textAnchor="middle">Electrical</text>
        </g>
      </svg>

      {/* Selected Sphere Info */}
      {selectedSphere && (
        <Card className="mt-4 sacred-card border border-sacred-gold/40">
          <CardContent className="p-4">
            {(() => {
              const sphere = treeGridSpheres.find(s => s.id === selectedSphere);
              if (!sphere) return null;

              return (
                <div className="text-center">
                  <div 
                    className="w-10 h-10 rounded-full mx-auto mb-3 border-2 border-white/30" 
                    style={{ backgroundColor: sphere.color }}
                  />
                  <h4 className="font-semibold text-white mb-2">
                    {sphere.name}
                  </h4>
                  <div className="flex justify-center gap-2 mb-3">
                    <Badge variant="outline" className="text-xs border-cosmic-500/30">
                      Dimension {sphere.dimension}
                    </Badge>
                    <Badge variant="outline" className="text-xs border-cosmic-500/30">
                      Sephirah
                    </Badge>
                  </div>
                  <p className="text-cosmic-300 text-sm">
                    {sphere.description}
                  </p>
                </div>
              );
            })()}
          </CardContent>
        </Card>
      )}
    </div>
  );
}

