      { value: 3, text: 'I actively help others on their spiritual path' },
      { value: 4, text: 'I have specific healing or teaching abilities I use' },
      { value: 5, text: 'I\'m in active service to planetary consciousness evolution' }
    ]
  }
];

export function SpiritualAssessment({ onComplete, className = "" }: SpiritualAssessmentProps) {
  const [currentQuestion, setCurrentQuestion] = useState(0);
  const [answers, setAnswers] = useState<Record<number, number>>({});
  const [isComplete, setIsComplete] = useState(false);
  const [results, setResults] = useState<AssessmentResults | null>(null);

  const handleAnswer = (questionId: number, value: number) => {
    setAnswers(prev => ({ ...prev, [questionId]: value }));
  };

  const nextQuestion = () => {
    if (currentQuestion < assessmentQuestions.length - 1) {
      setCurrentQuestion(prev => prev + 1);
    } else {
      calculateResults();
    }
  };

  const calculateResults = () => {
    const totalScore = Object.values(answers).reduce((sum, score) => sum + score, 0);
    const maxScore = assessmentQuestions.length * 5;
    const percentage = (totalScore / maxScore) * 100;

    let level: AssessmentResults['level'];
    let strengths: string[] = [];
    let areas_for_growth: string[] = [];
    let recommended_practices: string[] = [];

    // Determine level based on score
    if (percentage >= 85) {
      level = 'master';
      strengths = ['Advanced spiritual discernment', 'Strong protection abilities', 'Active service orientation'];
      recommended_practices = ['Teaching others', 'Advanced clearing work', 'Planetary grid work'];
    } else if (percentage >= 70) {
      level = 'advanced';
      strengths = ['Good spiritual awareness', 'Regular spiritual practice', 'Developing psychic abilities'];
      recommended_practices = ['Advanced lightbody work', 'Entity clearing training', 'Mentoring others'];
    } else if (percentage >= 55) {
      level = 'intermediate';
      strengths = ['Basic spiritual foundation', 'Growing awareness', 'Commitment to growth'];
      recommended_practices = ['Daily 12D Shield', 'Chakra clearing work', 'ES study program'];
    } else if (percentage >= 40) {
      level = 'developing';
      strengths = ['Openness to learning', 'Beginning awareness', 'Spiritual curiosity'];
      recommended_practices = ['Basic meditation', 'Energy protection', 'ES foundations course'];
    } else {
      level = 'beginner';
      strengths = ['Willingness to learn', 'Spiritual seeking', 'Open heart'];
      recommended_practices = ['Daily meditation practice', 'Basic energy awareness', 'ES beginner materials'];
    }

    // Analyze category strengths
    const categoryScores = assessmentQuestions.reduce((acc, q) => {
      acc[q.category] = (acc[q.category] || 0) + (answers[q.id] || 0);
      return acc;
    }, {} as Record<string, number>);

    const dominant_abilities = Object.entries(categoryScores)
      .sort(([,a], [,b]) => b - a)
      .slice(0, 3)
      .map(([category]) => category);

    // Identify areas for growth (lowest scoring categories)
    areas_for_growth = Object.entries(categoryScores)
      .sort(([,a], [,b]) => a - b)
      .slice(0, 2)
      .map(([category]) => category);

    const assessmentResults: AssessmentResults = {
      level,
      strengths,
      areas_for_growth,
      recommended_practices,
      spiritual_age: Math.floor(percentage / 10) + 1,
      dominant_abilities
    };

    setResults(assessmentResults);
    setIsComplete(true);
    onComplete?.(assessmentResults);
  };

  const resetAssessment = () => {
    setCurrentQuestion(0);
    setAnswers({});
    setIsComplete(false);
    setResults(null);
  };

  if (isComplete && results) {
    return (
      <div className={`space-y-6 ${className}`}>
        <Card className="sacred-card">
          <CardHeader className="text-center">
            <CardTitle className="text-3xl font-sacred text-sacred-gold">
              Your Spiritual Development Assessment
            </CardTitle>
            <div className="flex items-center justify-center gap-2 mt-4">
              <Badge className={`text-lg px-4 py-2 ${
                results.level === 'master' ? 'bg-sacred-gold text-cosmic-900' :
                results.level === 'advanced' ? 'bg-purple-600 text-white' :
                results.level === 'intermediate' ? 'bg-blue-600 text-white' :
                results.level === 'developing' ? 'bg-green-600 text-white' :
                'bg-cosmic-600 text-white'
              }`}>
                {results.level.toUpperCase()} LEVEL
              </Badge>
            </div>
          </CardHeader>
          <CardContent className="space-y-6">
            <div className="grid md:grid-cols-2 gap-6">
              <Card className="cosmic-card">
                <CardHeader>
                  <CardTitle className="text-lg text-sacred-gold flex items-center gap-2">
                    <Star className="w-5 h-5" />
                    Your Strengths
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  <ul className="space-y-2">
                    {results.strengths.map((strength, index) => (
                      <li key={index} className="flex items-center gap-2 text-cosmic-100">
                        <CheckCircle className="w-4 h-4 text-green-400" />
                        {strength}
                      </li>
                    ))}
                  </ul>
                </CardContent>
              </Card>

              <Card className="cosmic-card">
                <CardHeader>
                  <CardTitle className="text-lg text-cosmic-blue flex items-center gap-2">
                    <Target className="w-5 h-5" />
                    Growth Areas
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  <ul className="space-y-2">
                    {results.areas_for_growth.map((area, index) => (
                      <li key={index} className="flex items-center gap-2 text-cosmic-100">
                        <ArrowRight className="w-4 h-4 text-cosmic-blue" />
                        {area.replace('_', ' ')}
                      </li>
                    ))}
                  </ul>
                </CardContent>
              </Card>
            </div>

            <Card className="cosmic-card">
              <CardHeader>
                <CardTitle className="text-lg text-emerald-400 flex items-center gap-2">
                  <BookOpen className="w-5 h-5" />
                  Recommended Practices
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="grid md:grid-cols-2 gap-3">
                  {results.recommended_practices.map((practice, index) => (
                    <div key={index} className="p-3 bg-cosmic-800 rounded border border-emerald-400/20">
                      <span className="text-cosmic-100">{practice}</span>
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>

            <div className="text-center space-y-4">
              <p className="text-cosmic-300">
                Your spiritual development age: <span className="text-sacred-gold font-semibold">{results.spiritual_age} years</span>
              </p>
              <Button 
                onClick={resetAssessment}
                variant="outline"
                className="border-cosmic-600 text-cosmic-300 hover:bg-cosmic-800"
              >
                Take Assessment Again
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  const question = assessmentQuestions[currentQuestion];
  const progress = ((currentQuestion + 1) / assessmentQuestions.length) * 100;

  return (
    <div className={`space-y-6 ${className}`}>
      <Card className="sacred-card">
        <CardHeader>
          <CardTitle className="text-2xl font-sacred text-sacred-gold text-center">
            Spiritual Development Assessment
          </CardTitle>
          <p className="text-center text-cosmic-300">
            Question {currentQuestion + 1} of {assessmentQuestions.length}
          </p>
          <Progress value={progress} className="h-2" />
        </CardHeader>
        <CardContent className="space-y-6">
          <div className="text-center">
            <h3 className="text-xl font-semibold text-cosmic-100 mb-6">
              {question.question}
            </h3>
          </div>

          <RadioGroup
            value={answers[question.id]?.toString()}
            onValueChange={(value) => handleAnswer(question.id, parseInt(value))}
          >
            <div className="space-y-4">
              {question.options.map((option) => (
                <div key={option.value} className="flex items-center space-x-3">
                  <RadioGroupItem value={option.value.toString()} id={`option-${option.value}`} />
                  <Label 
                    htmlFor={`option-${option.value}`}
                    className="text-cosmic-100 cursor-pointer flex-1 p-3 rounded border border-cosmic-600 hover:border-sacred-gold/50 transition-colors"
                  >
                    {option.text}
                  </Label>
                </div>
              ))}
            </div>
          </RadioGroup>

          <div className="flex justify-between pt-6">
            <Button
              variant="outline"
              onClick={() => setCurrentQuestion(prev => Math.max(0, prev - 1))}
              disabled={currentQuestion === 0}
              className="border-cosmic-600 text-cosmic-300"
            >
              Previous
            </Button>

            <Button
              onClick={nextQuestion}
              disabled={!answers[question.id]}
              className="bg-sacred-gold text-cosmic-900 hover:bg-sacred-gold/80"
            >
              {currentQuestion === assessmentQuestions.length - 1 ? 'Complete Assessment' : 'Next Question'}
              <ArrowRight className="w-4 h-4 ml-2" />
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

