                    </ul>
                  </div>
                  <Button className="w-full sacred-button">
                    Apply to Become Mentor
                  </Button>
                </div>
              </CardContent>
            </Card>
          </div>
        </TabsContent>
      </Tabs>
    </div>
  );
}

