              <Select
                value={audioState.selectedFrequency}
                onValueChange={(value) => setAudioState(prev => ({ ...prev, selectedFrequency: value }))}
              >
                <SelectTrigger className="bg-cosmic-800 border-cosmic-600">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent className="bg-cosmic-800 border-cosmic-600">
                  {frequencies.map((freq) => (
                    <SelectItem key={freq.id} value={freq.id}>
                      <div className="flex items-center space-x-2">
                        <div 
                          className="w-3 h-3 rounded-full"
                          style={{ backgroundColor: freq.color }}
                        />
                        <span>{freq.name}</span>
                      </div>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {selectedFreq && (
              <Card className="bg-cosmic-800/50 border-cosmic-600">
                <CardContent className="p-4">
                  <div className="space-y-3">
                    <div className="flex items-center justify-between">
                      <h4 className="font-semibold text-white">{selectedFreq.name}</h4>
                      <Badge variant="outline" className={getCategoryColor(selectedFreq.category)}>
                        {selectedFreq.category}
                      </Badge>
                    </div>

                    <p className="text-sm text-cosmic-300">{selectedFreq.description}</p>

                    <div className="grid grid-cols-2 gap-4 text-sm">
                      <div>
                        <span className="text-cosmic-400">Base Frequency:</span>
                        <span className="text-sacred-gold ml-2">{selectedFreq.baseFreq.toFixed(2)} Hz</span>
                      </div>
                      <div>
                        <span className="text-cosmic-400">Beat Frequency:</span>
                        <span className="text-sacred-gold ml-2">{selectedFreq.beatFreq} Hz</span>
                      </div>
                    </div>

                    <div>
                      <span className="text-cosmic-400 text-sm">Benefits:</span>
                      <div className="flex flex-wrap gap-1 mt-1">
                        {selectedFreq.benefits.map((benefit, index) => (
                          <Badge key={index} variant="outline" className="text-xs border-cosmic-500/30 text-cosmic-400">
                            {benefit}
                          </Badge>
                        ))}
                      </div>
                    </div>
                  </div>
                </CardContent>
              </Card>
            )}
          </div>

          {/* Player Controls */}
          <div className="space-y-4">
            <div className="text-center">
              <div className="text-2xl font-mono font-bold text-sacred-gold mb-2">
                {formatTime(audioState.timeElapsed)}
              </div>
              <div className="flex justify-center space-x-4">
                <Button
                  onClick={togglePlayback}
                  className="w-16 h-16 rounded-full sacred-button"
                  size="lg"
                >
                  {audioState.isPlaying ? (
                    <Pause className="w-6 h-6" />
                  ) : (
                    <Play className="w-6 h-6" />
                  )}
                </Button>

                <Button
                  onClick={resetTimer}
                  variant="outline"
                  size="lg"
                  className="w-16 h-16 rounded-full border-cosmic-500 text-cosmic-500 hover:bg-cosmic-500 hover:text-white"
                >
                  <RotateCcw className="w-6 h-6" />
                </Button>
              </div>
            </div>

            {/* Volume Control */}
            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <label className="text-sm font-medium text-cosmic-100 flex items-center">
                  {audioState.volume === 0 ? (
                    <VolumeX className="w-4 h-4 mr-2" />
                  ) : (
                    <Volume2 className="w-4 h-4 mr-2" />
                  )}
                  Volume
                </label>
                <span className="text-sm text-sacred-gold">{audioState.volume}%</span>
              </div>
              <Slider
                value={[audioState.volume]}
                onValueChange={(value) => setAudioState(prev => ({ ...prev, volume: value[0] }))}
                max={100}
                step={5}
                className="w-full"
              />
            </div>
          </div>

          {/* Visual Feedback */}
          {audioState.isPlaying && (
            <div className="text-center space-y-2">
              <div className="flex justify-center items-center space-x-2">
                <Brain className="w-5 h-5 text-sacred-gold animate-pulse" />
                <span className="text-sm text-cosmic-100">Binaural beats active</span>
                <div className="flex space-x-1">
                  {[...Array(3)].map((_, i) => (
                    <div
                      key={i}
                      className="w-2 h-2 bg-sacred-gold rounded-full animate-ping"
                      style={{ animationDelay: `${i * 0.2}s` }}
                    />
                  ))}
                </div>
              </div>
              <p className="text-xs text-cosmic-400">
                Use stereo headphones for optimal binaural effect
              </p>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Quick Access Frequencies */}
      <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-4">
        {frequencies.filter(f => ['alpha-waves', 'theta-waves', 'heart-chakra', 'gamma-waves'].includes(f.id)).map((freq) => (
          <Card 
            key={freq.id}
            className={`sacred-card cursor-pointer transition-all duration-300 ${
              audioState.selectedFrequency === freq.id ? 'border-sacred-gold/60' : 'hover:border-sacred-gold/30'
            }`}
            onClick={() => setAudioState(prev => ({ ...prev, selectedFrequency: freq.id }))}
          >
            <CardContent className="p-4">
              <div className="space-y-3">
                <div className="flex items-center space-x-3">
                  <div 
                    className="w-4 h-4 rounded-full"
                    style={{ backgroundColor: freq.color }}
                  />
                  <h4 className="font-semibold text-white text-sm">{freq.name}</h4>
                </div>
                <p className="text-xs text-cosmic-300">{freq.description}</p>
                <div className="text-xs text-cosmic-400">
                  {freq.baseFreq.toFixed(0)} Hz • {freq.beatFreq} Hz beat
                </div>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  );
}

client/src/components/building-blocks/ad.content:
import { useState, useEffect, useRef, useMemo } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Search, Filter, X, Tag, Clock, BookOpen, Sparkles } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent } from "@/components/ui/card";
import { useMobileOptimizations } from "@/hooks/use-mobile-optimizations";

interface SearchResult {
  id: string;
  title: string;
  description: string;
  category: 'spiritual' | 'tools' | 'knowledge' | 'practice';
  tags: string[];
  relevance: number;
  path: string;
  lastUpdated?: Date;
}

interface AdvancedSearchProps {
  isOpen: boolean;
  onClose: () => void;
  placeholder?: string;
  results?: SearchResult[];
  onSearch?: (query: string, filters: SearchFilters) => void;
}

interface SearchFilters {
  categories: string[];
  tags: string[];
  timeRange: 'all' | 'recent' | 'week' | 'month';
  sortBy: 'relevance' | 'date' | 'title';
}

const defaultFilters: SearchFilters = {
  categories: [],
  tags: [],
  timeRange: 'all',
  sortBy: 'relevance',
};

const categories = [
  { id: 'spiritual', label: 'Spiritual Systems', icon: <Sparkles className="w-4 h-4" />, color: 'sacred-gold' },
  { id: 'tools', label: 'Practice Tools', icon: <Tag className="w-4 h-4" />, color: 'cosmic-400' },
  { id: 'knowledge', label: 'Knowledge Base', icon: <BookOpen className="w-4 h-4" />, color: 'cosmic-300' },
  { id: 'practice', label: 'Practical Guides', icon: <Clock className="w-4 h-4" />, color: 'cosmic-200' },
];

const mockResults: SearchResult[] = [
  {
    id: '1',
    title: '15-Chakra System Activation',
    description: 'Complete guide to activating all 15 chakras including morphogenetic layers',
    category: 'spiritual',
    tags: ['chakras', 'activation', 'morphogenetic'],
    relevance: 0.95,
    path: '/chakras',
    lastUpdated: new Date('2024-01-15'),
  },
  {
    id: '2',
    title: '12D Shield Protection Technique',
    description: 'Essential spiritual protection method using 12-dimensional shield',
    category: 'practice',
    tags: ['protection', '12D shield', 'defense'],
    relevance: 0.88,
    path: '/psychic-self-defense',
    lastUpdated: new Date('2024-01-20'),
  },
];

export function AdvancedSearch({ 
  isOpen, 
  onClose, 
  placeholder = "Search spiritual knowledge, tools, and practices...",
  results = mockResults,
  onSearch 
}: AdvancedSearchProps) {
  const [query, setQuery] = useState("");
  const [filters, setFilters] = useState<SearchFilters>(defaultFilters);
  const [showFilters, setShowFilters] = useState(false);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const { viewport, touchDevice } = useMobileOptimizations();

  useEffect(() => {
    if (isOpen && searchInputRef.current) {
      setTimeout(() => searchInputRef.current?.focus(), 100);
    }
  }, [isOpen]);

  const filteredResults = useMemo(() => {
    return results.filter(result => {
      const searchTerms = query.toLowerCase().split(' ');
      const searchableText = `${result.title} ${result.description} ${result.tags.join(' ')}`.toLowerCase();
      return query === '' || searchTerms.every(term => searchableText.includes(term));
    });
  }, [results, query]);

  const getTouchClasses = () => {
    return touchDevice.isTouch 
      ? "active:scale-95 transition-transform" 
      : "hover:bg-cosmic-700/50 transition-colors";
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm"
          onClick={onClose}
        >
          <motion.div
            initial={{ opacity: 0, scale: 0.9, y: 20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.9, y: 20 }}
            transition={{ type: "spring", duration: 0.5 }}
            className={`
              fixed top-4 left-4 right-4 bottom-4 
              ${viewport.isMobile ? 'top-2 left-2 right-2 bottom-2' : 'top-16 left-1/2 -translate-x-1/2 w-full max-w-4xl bottom-16'}
              bg-cosmic-900 border border-sacred-gold/20 rounded-2xl shadow-2xl
              flex flex-col overflow-hidden
            `}
            onClick={(e) => e.stopPropagation()}
          >
            <div className="p-6 border-b border-cosmic-700">
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-2xl font-sacred text-sacred-gold">
                  Spiritual Search
                </h2>
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={onClose}
                  className={`text-cosmic-300 hover:text-sacred-gold ${getTouchClasses()}`}
                >
                  <X className="w-5 h-5" />
                </Button>
              </div>

              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-cosmic-400" />
                <Input
                  ref={searchInputRef}
                  value={query}
                  onChange={(e) => setQuery(e.target.value)}
                  placeholder={placeholder}
                  className="pl-10 pr-12 bg-cosmic-800 border-cosmic-600 text-white placeholder:text-cosmic-400 text-base"
                  style={{ fontSize: '16px' }}
                />
              </div>
            </div>

            <div className="flex-1 overflow-y-auto p-6">
              <div className="space-y-4">
                {filteredResults.map((result, index) => (
                  <motion.div
                    key={result.id}
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: index * 0.05 }}
                  >
                    <Card className={`
                      bg-cosmic-800/50 border-cosmic-600 cursor-pointer transition-all
                      hover:border-sacred-gold/50 hover:bg-cosmic-700/50
                      ${getTouchClasses()}
                    `}>
                      <CardContent className="p-4">
                        <h3 className="font-semibold text-cosmic-100 mb-2">
                          {result.title}
                        </h3>
                        <p className="text-cosmic-300 text-sm mb-3">
                          {result.description}
                        </p>
                        <div className="flex flex-wrap gap-1">
                          {result.tags.map((tag) => (
                            <Badge
                              key={tag}
                              variant="secondary"
                              className="text-xs bg-cosmic-700 text-cosmic-200"
                            >
                              {tag}
                            </Badge>
                          ))}
                        </div>
                      </CardContent>
                    </Card>
                  </motion.div>
                ))}
              </div>
            </div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

