import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { chakraData, getChakraColors, type ChakraData } from "@/lib/chakra-data";
import { BookOpen, Zap, Heart, Eye, Lightbulb } from "lucide-react";

interface ChakraVisualizationProps {
  selectedChakra?: ChakraData | null;
  onChakraSelect: (chakra: ChakraData) => void;
}

export function ChakraVisualization({ selectedChakra, onChakraSelect }: ChakraVisualizationProps) {


  const chakraColors = getChakraColors();

  const ChakraPoint = ({ chakra }: { chakra: ChakraData }) => {
    const isSelected = selectedChakra?.id === chakra.id;
    const color = chakraColors[chakra.id as keyof typeof chakraColors];
    const [isHovered, setIsHovered] = useState(false);

    return (
      <div
        className="chakra-container absolute"
        style={{
          left: `${chakra.position.x}%`,
          top: `${chakra.position.y}%`,
          transform: 'translate(-50%, -50%)',
          zIndex: 30,
        }}
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
      >
        {/* Outer energy pulse ring */}
        <div
          className={`absolute inset-0 rounded-full transition-all duration-700 ${
            isHovered || isSelected ? 'animate-pulse-energy' : ''
          }`}
          style={{
            width: '72px',
            height: '72px',
            transform: 'translate(-50%, -50%)',
            left: '50%',
            top: '50%',
            background: `radial-gradient(circle, transparent 60%, ${color}20 70%, transparent 100%)`,
            opacity: isHovered || isSelected ? 1 : 0,
            animation: isHovered || isSelected ? 'energyPulse 2s ease-in-out infinite' : 'none'
          }}
        />

        {/* Middle energy ring */}
        <div
          className={`absolute inset-0 rounded-full transition-all duration-500 ${
            isHovered || isSelected ? 'animate-pulse-secondary' : ''
          }`}
          style={{
            width: '54px',
            height: '54px',
            transform: 'translate(-50%, -50%)',
            left: '50%',
            top: '50%',
            background: `radial-gradient(circle, transparent 50%, ${color}40 65%, transparent 100%)`,
            opacity: isHovered || isSelected ? 0.8 : 0,
            animation: isHovered || isSelected ? 'energyPulseSecondary 1.5s ease-in-out infinite 0.3s' : 'none'
          }}
        />

        {/* Enhanced chakra point with dynamic sizing and effects */}
        <button
          className={`chakra-point relative transition-all duration-500 focus:outline-none focus:ring-2 focus:ring-sacred-gold ${
            isSelected ? 'selected' : ''
          } ${chakra.category === 'morphogenetic' ? 'morphogenetic-chakra' : 'physical-chakra'}`}
          style={{
            background: chakra.category === 'morphogenetic' 
              ? `conic-gradient(from 0deg, ${color}, transparent, ${color}, transparent, ${color})` 
              : `radial-gradient(circle, ${color} 0%, ${color}dd 50%, ${color}aa 100%)`,
            backgroundSize: chakra.category === 'morphogenetic' ? '200% 200%' : 'auto',
            width: chakra.category === 'morphogenetic' ? '32px' : '40px',
            height: chakra.category === 'morphogenetic' ? '32px' : '40px',
            borderRadius: '50%',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            cursor: 'pointer',
            border: `3px solid ${isSelected ? '#FFD700' : isHovered ? 'rgba(255, 255, 255, 0.8)' : 'rgba(255, 255, 255, 0.4)'}`,
            boxShadow: `
              0 0 ${isSelected || isHovered ? '35px' : '20px'} ${color}${chakra.category === 'morphogenetic' ? '70' : '60'},
              inset 0 0 ${isSelected || isHovered ? '15px' : '8px'} ${color}20,
              0 0 ${isSelected || isHovered ? '50px' : '30px'} ${color}40
            `,
            opacity: isSelected ? 1 : 0.85,
            transform: `
              scale(${isHovered ? 1.2 : isSelected ? 1.15 : 1}) 
              ${chakra.category === 'morphogenetic' && (isHovered || isSelected) ? 'rotate(45deg)' : 'rotate(0deg)'}
            `,
            zIndex: isSelected ? 50 : isHovered ? 40 : 10,
            transition: 'all 0.5s cubic-bezier(0.4, 0, 0.2, 1)',
            color: color,
            filter: isHovered || isSelected ? 'brightness(1.2) saturate(1.3)' : 'brightness(1)',
            animation: chakra.category === 'morphogenetic' ? 'morphogeneticPulse 3s ease-in-out infinite' : 'none'
          }}
          onClick={(e) => {
            e.preventDefault();
            e.stopPropagation();
            onChakraSelect(chakra);
          }}
          onMouseEnter={() => setIsHovered(true)}
          onMouseLeave={() => setIsHovered(false)}
          aria-label={`Select ${chakra.name}`}
          title={`${chakra.name} - ${chakra.function}`}
        >
          <div className="relative flex items-center justify-center">
            <span className="text-sm font-bold text-white drop-shadow-lg z-10">
              {chakra.id}
            </span>
            {/* Inner rotating ring for morphogenetic chakras */}
            {chakra.category === 'morphogenetic' && (
              <div 
                className="absolute inset-0 rounded-full border border-white/30 animate-spin"
                style={{ 
                  animationDuration: '8s',
                  animationDirection: chakra.id % 2 === 0 ? 'normal' : 'reverse'
                }}
              />
            )}
          </div>
        </button>

        {/* Energy particles on hover */}
        {isHovered && (
          <>
            <div
              className="absolute animate-spin-slow"
              style={{
                width: '8px',
                height: '8px',
                background: color,
                borderRadius: '50%',
                left: '60%',
                top: '20%',
                opacity: 0.7,
                animation: 'floatParticle 3s ease-in-out infinite'
              }}
            />
            <div
              className="absolute animate-spin-slow"
              style={{
                width: '6px',
                height: '6px',
                background: color,
                borderRadius: '50%',
                left: '20%',
                top: '60%',
                opacity: 0.6,
                animation: 'floatParticle 2.5s ease-in-out infinite 0.5s'
              }}
            />
            <div
              className="absolute animate-spin-slow"
              style={{
                width: '4px',
                height: '4px',
                background: color,
                borderRadius: '50%',
                left: '80%',
                top: '70%',
                opacity: 0.5,
                animation: 'floatParticle 2s ease-in-out infinite 1s'
              }}
            />
          </>
        )}
      </div>
    );
  };

  return (
    <div className="grid md:grid-cols-1 lg:grid-cols-2 gap-6 lg:gap-12 items-start lg:items-center">
      {/* Chakra Visualization */}
      <div className="relative">
        <div className="cosmic-gradient sacred-geometry rounded-3xl p-4 md:p-8 relative overflow-hidden min-h-[500px] md:min-h-[700px]">
          <div className="absolute inset-0 sacred-geometry-bg opacity-20"></div>

          {/* Debug Info */}
          <div className="absolute top-4 right-4 z-40 text-xs text-white/60">
            Total Chakras: {chakraData.length}
          </div>

          {/* Human figure and chakra system */}
          <div className="relative z-10 w-full h-full flex items-center justify-center min-h-[500px] md:min-h-[700px]">
            <svg 
              viewBox="0 0 200 120" 
              className="w-full max-w-xs md:max-w-md h-full opacity-60"
              style={{ position: 'absolute' }}
            >
              {/* Anatomically accurate human figure with golden ratio proportions */}
              <g stroke="rgba(255, 215, 0, 0.5)" strokeWidth="1.2" fill="none">
                {/* Head - proper proportional size */}
                <circle cx="100" cy="18" r="6.5" />
                {/* Neck */}
                <line x1="100" y1="24.5" x2="100" y2="28" />
                {/* Shoulders - accurate width */}
                <line x1="84" y1="30" x2="116" y2="30" />
                {/* Arms - natural positioning */}
                <line x1="84" y1="30" x2="76" y2="52" />
                <line x1="116" y1="30" x2="124" y2="52" />
                {/* Torso - correct proportions */}
                <line x1="100" y1="28" x2="100" y2="68" />
                {/* Chest/Heart area outline */}
                <circle cx="100" cy="40" r="8" fill="none" opacity="0.3" />
                {/* Solar plexus area */}
                <circle cx="100" cy="50" r="6" fill="none" opacity="0.2" />
                {/* Waist */}
                <line x1="92" y1="60" x2="108" y2="60" />
                {/* Pelvis outline */}
                <ellipse cx="100" cy="65" rx="6" ry="4" fill="none" opacity="0.3" />
                {/* Legs - proper proportional length */}
                <line x1="95" y1="70" x2="90" y2="100" />
                <line x1="105" y1="70" x2="110" y2="100" />
                {/* Central channel - Sushumna */}
                <line x1="100" y1="12" x2="100" y2="105" stroke="rgba(255, 215, 0, 0.6)" strokeWidth="1.5" strokeDasharray="2,2" />
                {/* Ida and Pingala nadis */}
                <path d="M100,15 Q90,25 100,35 Q110,45 100,55 Q90,65 100,75 Q110,85 100,95" 
                      stroke="rgba(255, 192, 203, 0.4)" strokeWidth="1" fill="none" />
                <path d="M100,15 Q110,25 100,35 Q90,45 100,55 Q110,65 100,75 Q90,85 100,95" 
                      stroke="rgba(173, 216, 230, 0.4)" strokeWidth="1" fill="none" />
              </g>
            </svg>

            {/* All 15 Chakra points positioned anatomically */}
            {chakraData.map((chakra) => (
              <ChakraPoint key={chakra.id} chakra={chakra} />
            ))}

            {/* Energy connections between chakras */}
            <svg 
              viewBox="0 0 200 100" 
              className="absolute inset-0 w-full h-full pointer-events-none"
              style={{ zIndex: 5 }}
            >
              {/* Central channel energy line */}
              <line 
                x1="50%" y1="5%" 
                x2="50%" y2="95%" 
                stroke="rgba(255, 215, 0, 0.3)" 
                strokeWidth="2"
                className="animate-pulse"
              />

              {/* Morphogenetic field connections */}
              {chakraData.filter(c => c.category === 'morphogenetic').map((chakra, index) => (
                <g key={`connection-${chakra.id}`}>
